const i = $.input;
const perPage = Math.max(1, Math.min(100, i.maxContacts || 25));
const params = { page: '1', per_page: String(perPage) };

if (i.personTitles && i.personTitles.length) {
  i.personTitles.forEach((t, idx) => { params['person_titles[' + idx + ']'] = t; });
}
if (i.personSeniorities && i.personSeniorities.length) {
  i.personSeniorities.forEach((s, idx) => { params['person_seniorities[' + idx + ']'] = s; });
}
if (i.personLocations && i.personLocations.length) {
  i.personLocations.forEach((l, idx) => { params['person_locations[' + idx + ']'] = l; });
}
if (i.organizationDomains && i.organizationDomains.length) {
  i.organizationDomains.forEach((d, idx) => { params['q_organization_domains_list[' + idx + ']'] = d; });
}
if (i.employeeRanges && i.employeeRanges.length) {
  i.employeeRanges.forEach((r, idx) => { params['organization_num_employees_ranges[' + idx + ']'] = r; });
}
if (i.technologies && i.technologies.length) {
  i.technologies.forEach((t, idx) => { params['currently_using_any_of_technology_uids[' + idx + ']'] = t; });
}

return { params, perPage };

const resp = $.steps.searchPeople.response || {};
const people = resp.people || [];
if (people.length === 0) throw new Error('No people found matching your criteria. Try broadening your search filters.');
return { people, count: people.length, totalAvailable: resp.total_entries || 0 };

const resp = $.steps.createContact?.response;
if (!resp || !resp.contact) return { contactId: null, skipped: true };
return { contactId: resp.contact.id, name: resp.contact.name, skipped: false };

const iterations = $.steps.createContacts?.response?.iterations || [];
const contactIds = iterations
  .map(r => r?.extractContactId?.output)
  .filter(o => o && !o.skipped && o.contactId)
  .map(o => o.contactId);

if (contactIds.length === 0) throw new Error('No contacts were created. Check your Apollo plan and API key permissions.');

return { contactIds, count: contactIds.length };

const contactIds = $.steps.collectContactIds.output.contactIds;
const sequenceId = $.input.sequenceId;
const emailAccountId = $.input.emailAccountId;

const params = {
  emailer_campaign_id: sequenceId,
  send_email_from_email_account_id: emailAccountId,
  sequence_active_in_other_campaigns: 'true'
};
contactIds.forEach((id, idx) => { params['contact_ids[' + idx + ']'] = id; });

return { params, sequenceId };

const searchCount = $.steps.extractPeople.output.count;
const totalAvailable = $.steps.extractPeople.output.totalAvailable;
const contactsCreated = $.steps.collectContactIds.output.count;
const seqResp = $.steps.addToSequence.response || {};
const addedContacts = (seqResp.contacts || []).length;
const skipped = seqResp.skipped_contact_ids ? Object.keys(seqResp.skipped_contact_ids).length : 0;
const campaign = seqResp.emailer_campaign || {};

return {
  pipeline: {
    peopleFound: totalAvailable,
    peopleProcessed: searchCount,
    contactsCreated,
    addedToSequence: addedContacts,
    skippedFromSequence: skipped
  },
  sequence: {
    id: campaign.id || $.input.sequenceId,
    name: campaign.name || 'Unknown',
    active: campaign.active || false
  },
  summary: `Prospected ${searchCount} people from ${totalAvailable.toLocaleString()} matches. Created ${contactsCreated} contacts. Added ${addedContacts} to sequence "${campaign.name || 'Unknown'}" (${skipped} skipped).`
};
